Download().ContinueWith(t =>
{
    if (t.IsFaulted)
        Log(t.Exception!.InnerException);   // настоящая ошибка внутри Aggregate
    else if (!t.IsCanceled)
        Show(t.Result);
}, TaskScheduler.Default);

